from lib import *
S = SS('c15')
steps = [
    step("在本机起一个 registry:2 容器(端口 9700),registry 就是一个 HTTP 服务:GET /v2/ 返回 200,响应头 Docker-Distribution-Api-Version = registry/2.0,正文是 {}。客户端靠这个请求确认对面支持 v2 API。", t=tl(S(1)), done=lidx(S(1), 'GET /v2/'), kv=KV([['入口', 'GET /v2/ → 200'], ['版本头', 'Docker-Distribution-Api-Version: registry/2.0'], ['正文', '{}']], ['入口'])),
    step("docker push 在 registry 的访问日志里是 14 个请求:先对 4 个 blob(3 层加 1 个 config)各发一次 HEAD,全部 404(registry 里还没有);然后 4 次 POST /blobs/uploads/(202)开启上传,4 次 PUT /blobs/uploads/<uuid>(201)把内容写进去;最后 HEAD manifests/1 → 404,PUT manifests/1 → 201。顺序是先传 blob,最后才传 manifest。", t=tl(S(2)), done=lidx(S(2), 'PUT   /v2/c15/app/manifests/1'), mark=lidx(S(2), 'POST', 'PUT   /v2/c15/app/blobs/uploads'), b=bars([['HEAD blob(404)', 4, '4'], ['POST 开启上传', 4, '4'], ['PUT 写入 blob', 4, '4'], ['HEAD+PUT manifest', 2, '2']], 4, done=[3], mark=[1, 2]), kv=KV([['第一步', '4 个 blob 各 HEAD 一次,404'], ['第二步', '4 次 POST + 4 次 PUT 上传'], ['最后', 'PUT manifest → 201']], ['最后'])),
    step("删掉本地镜像的名字再 docker pull,registry 只收到 1 个请求:HEAD manifests/1 → 200;输出里有 2 行 Already exists。因为本机的 containerd 内容库里还留着这些层,docker 只确认了 tag 指向的内容就完事。镜像已经是最新时再 pull 一次,同样只有 1 个 HEAD。", t=tl(S(3)), done=lidx(S(3), 'Already exists'), mark=lidx(S(3), 'HEAD  /v2/c15/app/manifests/1'), kv=KV([['本地还有层', 'pull 只发 1 个 HEAD manifest'], ['输出', '2 行 Already exists']], ['本地还有层'])),
    step("真正“从零拉取”的请求:不通过 docker,用 Python 直接 HTTP 往 registry 手工上传一个镜像(层 119 字节、config 194 字节、manifest 418 字节,每次上传都返回 201),再 docker pull。registry 收到 4 个请求:HEAD manifests/v1 → 200;GET manifests/sha256:596dee… → 200;GET blobs/sha256:0046d1… → 200;GET blobs/sha256:de1bc8… → 200——先按 tag 问一下,再按摘要取 manifest,最后按摘要取两个 blob。拉下来的镜像只有 1 层,diff_id 与我写进 config 的相同。", t=tl(S(4)), done=lidx(S(4), 'GET   /v2/c15/hand/blobs'), mark=lidx(S(4), 'HEAD  /v2/c15/hand/manifests/v1', 'GET   /v2/c15/hand/manifests'), b=bars([['HEAD manifest(按 tag)', 1, '1'], ['GET manifest(按摘要)', 1, '1'], ['GET blob', 2, '2']], 2, done=[2], mark=[0, 1]), kv=KV([['1', 'HEAD manifests/&lt;tag&gt;'], ['2', 'GET manifests/<digest>'], ['3', 'GET blobs/<config>、GET blobs/<layer>']], ['2'])),
    step("自己用 HTTP 读 registry:GET /v2/_catalog 列出仓库(c15/app、c15/hand);GET /v2/c15/app/tags/list 返回 tags [\"1\"]。带 Accept 为 OCI manifest 取 manifests/1 → 200,正文 856 字节,响应头 Docker-Content-Digest 对正文自己算 sha256 一致;不带 Accept 头、或只接受 Docker schema2 类型,同一个 tag 都是 404。按摘要 HEAD manifest → 200,Content-Length 856;GET config blob 1038 字节,sha256 与摘要一致;不存在的 tag 是 404 加 MANIFEST_UNKNOWN 的 JSON,不存在的 blob 也是 404。", t=tl(S(5)), done=lidx(S(5), '自己对正文算 sha256 一致吗?True', 'sha256 与 digest 一致吗?True'), mark=lidx(S(5), '不带 Accept', '只接受 Docker schema2'), kv=KV([['Accept 匹配', '200'], ['Accept 不匹配', '404(这个 registry)'], ['校验', 'Docker-Content-Digest = 正文的 sha256']], ['Accept 不匹配'])),
]
A = mkartc('c15', 15, 'Docker,registry,Registry v2 API,docker pull,docker push,HTTP,真实验证,动画演示',
    '在本机 registry:2 上实测 docker push / pull 的 HTTP 请求:push 是 14 个请求(4 个 blob 先 HEAD 404、再 POST+PUT 上传,最后才 PUT manifest);本地还有层时 pull 只发 1 个 HEAD;从零拉取手工上传的镜像是 HEAD manifest、GET manifest(按摘要)、GET 两个 blob 共 4 个请求;registry 的 Accept 头不匹配时 manifest 返回 404。',
    'docker pull 到底向 registry 发了什么?这篇在本机起一个 registry,直接读它的访问日志,把 push 和 pull 的每一个 HTTP 请求列出来,再亲手用 HTTP 上传一个镜像、读 manifest 和 blob。',
    [('14 个请求', 'docker push 一个 3 层的镜像:4 次 HEAD blob、4 次 POST、4 次 PUT blob、HEAD 和 PUT manifest 各一次'), ('1 个请求', '本机还留着层内容时,docker pull 只发了一个 HEAD manifests/&lt;tag&gt;'), ('4 个请求', '从零拉取:HEAD manifest、GET manifest、GET 两个 blob')],
    [('入口 /v2/', '<p>registry:2 是一个普通的 HTTP 服务。<code>GET /v2/</code> 返回 200 和响应头 <code>Docker-Distribution-Api-Version: registry/2.0</code>。我是在本机的 registry:2 容器上做的实验,不同的 registry 实现(Docker Hub、Harbor 等)的细节可能不同,没有测。</p>'),
     ('push 的顺序', '<p>先对每个 blob 发 HEAD,404 就说明 registry 里没有;再 POST 开启上传、PUT 写入;所有 blob 到位后,最后才 PUT manifest。顺序保证了 manifest 引用到的内容在它出现时一定已经存在。请求次数来自 registry 的访问日志。</p>'),
     ('本地有层时的 pull', '<p>删掉镜像的名字后重新 pull,registry 只收到一个 <code>HEAD manifests/1</code>,docker 输出 2 行 <code>Already exists</code>——本机还留着内容。别用这种方式去估算“拉一个镜像要多少请求”。</p>'),
     ('从零拉取', '<p>要看完整的 pull,就得拉本机从没有过的内容。我用 Python 手工往 registry 上传一个只有一层的镜像(用到的正是 c14 讲的结构:config、layer 两个 blob 加一个 manifest),再 docker pull:HEAD manifest(按 tag)、GET manifest(按摘要)、GET config blob、GET layer blob,共 4 个请求。</p>'),
     ('自己读 registry', '<p>_catalog、tags/list 返回 JSON;manifest 的响应头 <code>Docker-Content-Digest</code> 就是正文的 sha256,blob 同理,客户端可以自己校验。这个 registry 在 Accept 头不包含 OCI manifest 类型时返回 404 和一份 JSON(正文我没有记录),不是 406,所以自己写客户端要带对 Accept。</p>')],
    steps,
    [ENV_C + '。registry 用 registry:2(经 dpull.py 下载后 docker load),运行在本机 127.0.0.1:9700,所有请求来自它自己的访问日志(路径里的 uuid 和摘要缩写显示);HTTP 客户端用 Python urllib;镜像和容器在实验后已删除',
     '没有验证:带认证的 registry(token 流程、401 与 WWW-Authenticate)、Docker Hub 的行为、分块上传(PATCH)、跨仓库 blob 挂载(mount)、并发拉取多个层的顺序、HTTPS 与证书、registry 的 GC'],
    'Registry v2 API')
